import math

def is_power_of_p(N, p):
    """Checks if N is a power of p (p^k, k >= 1)."""
    if N <= 0:
        return False
    if N == 1:
        # If p > 1, 1 = p^0, but since we expect results >= 2, we might treat k>=1 strictly.
        # Given a, b >= 1 and p > 2, the expressions are always >= 2.
        return False 

    while N > 1 and N % p == 0:
        N //= p

    return N == 1

primes = [3, 5, 7]
max_ab = 5
successes = []

print("Starting test...")

for p in primes:
    print(f"Testing prime p = {p}")
    for a in range(1, max_ab + 1):
        for b in range(a, max_ab + 1):
            # Check the conditions
            A = a**(p - 1) + b
            B = b**(p - 1) + a

            is_A_power = is_power_of_p(A, p)
            is_B_power = is_power_of_p(B, p)

            if is_A_power and is_B_power:
                successes.append((p, a, b, A, B))
                print(f"  Found success: ({p}, {a}, {b}). A={A}, B={B}")

print("\n--- Test Complete ---")
if successes:
    print("Found solutions:")
    for s in successes:
        print(s)
else:
    print("No solutions found in the tested range.")

# Write results to notes for later use
note_text = "Small Case Search Results (p in {3, 5, 7}, 1 <= a <= b <= 5):\n"
if successes:
    note_text += "Successful triples (p, a, b) found:\n"
    for p, a, b, A, B in successes:
        note_text += f"  ({p}, {a}, {b}) -> A = {A} = {p}^k_A, B = {B} = {p}^k_B\n"
else:
    note_text += "No successful triples found in the tested range.\n"

print("\n--- Suggested Note Content ---\n" + note_text)

